>>> B = Symbol('B',commutative=False)
    >>> C = Symbol('C',commutative=False)
    >>> D = Symbol('D',commutative=False)

    First see what happens to products of tensor products:

    >>> e = TensorProduct(A,B)*TensorProduct(C,D)
    >>> e
    AxB*CxD
    >>> tensor_product_simp(e)
    (A*C)x(B*D)

    This is the core logic of this function, and it works inside, powers, sums,
    commutators and anticommutators as well:

    >>> tensor_product_simp(e**2)
    (A*C)x(B*D)**2

    """
    if isinstance(e, Add):
        return Add(*[tensor_product_simp(arg) for arg in e.args])
    elif isinstance(e, Pow):
        # Handle powers of TensorProducts
        if isinstance(e.base, TensorProduct):
            # Only handle positive integer exponents
            if e.exp.is_Integer and e.exp > 0:
                # TensorProduct**n equals TensorProduct of each argument raised to n
                # TensorProduct(a,b)**2 = TensorProduct(a,b)*TensorProduct(a,b) = TensorProduct(a*a, b*b)
                new_args = [arg**e.exp for arg in e.base.args]
                return TensorProduct(*new_args)
        return tensor_product_simp(e.base) ** e.exp
    elif isinstance(e, Mul):
        return tensor_product_simp_Mul(e)
    elif isinstance(e, Commutator):
        return Commutator(*[tensor_product_simp(arg) for arg in e.args])
    elif isinstance(e, AntiCommutator):
        return AntiCommutator(*[tensor_product_simp(arg) for arg in e.args])
    else:
        return e

